create table public.assessments (id uuid primary key default gen_random_uuid(), project_submission_id uuid not null references public.project_submissions(id) on delete restrict, rubric_id uuid not null references public.rubrics(id) on delete restrict, teacher_id uuid not null references public.profiles(id) on delete restrict, score numeric(6,2) not null check (score between 0 and 100), feedback text, result jsonb, assessed_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());;
